import revisions from '../app/report-quality-revisions.json' with {type:'json'};
import {bindReportInterviewOwner} from './source-question-presentation.mjs';

// One current practical revision, separate from source evidence. No parallel
// historical project editions are generated by this layer.
export const reportQualityVersion = revisions.version;
export const reportInterviewReviews = () => revisions.interviewReviews ?? {};
export function reportInterviewFields(id, source) {
  const reviews=reportInterviewReviews();
  if(!source||!Object.hasOwn(reviews,id))return {};
  const interviewReview=reviews[id];
  // Current report metadata, never the receipt's own claimed edition/hash.
  return {interviewReview,edition:String(source.year),sourceHash:source.source_hash};
}
export function reportQualityFor(id) { return revisions.entries.find(entry => entry.id === id); }
export function reportQualityPhaseText(line,phase) {
  if(!line?.practicalRevision)return undefined;
  const entry=reportQualityFor(line.id);
  if(!entry)return undefined;
  return entry.points.filter(p=>p.changes.phases[phase]?.status==='APPLICABLE').map(p=>{
    const plan=p.changes.phases[phase];
    return p.id+'\n'+plan.procedure+'\nBewijs: '+plan.evidence+'\nBeperking: '+plan.boundary;
  }).join('\n\n');
}
export function revisedReportLine(line, source) {
  const entry = reportQualityFor(line.id);
  const interview=reportInterviewFields(line.id, source);
  const bind=value=>source?bindReportInterviewOwner(value,Object.hasOwn(interview,'interviewReview')?interview:null):value;
  if (!entry) return bind(line);
  const procedure=entry.points.map(p=>p.id+'\n'+Object.entries(p.changes.phases)
    .filter(([,phase])=>phase.status==='APPLICABLE')
    .map(([name,phase])=>name.toUpperCase()+'\n'+phase.procedure+'\nBewijs: '+phase.evidence+'\nBeperking: '+phase.boundary).join('\n\n')).join('\n\n');
  return bind({...line, ...structuredClone(entry.line), objective: structuredClone(entry.goal),
    practicalGenericGoal: entry.genericGoal,
    controlObjective: structuredClone(entry.controlObjective), practicalRevision: reportQualityVersion,
    procedure: entry.line.procedure?structuredClone(entry.line.procedure):
      {...line.procedure,text:procedure,basis:'PROPOSED',reason:'Actuele toetsuitwerking per gekoppeld toetspunt; geen historische bevinding of bewijs van ingevoerde beheersing.'}});
}
export function revisedReportBlock(block) {
  const entry = reportQualityFor(block.id);
  if (!entry) return block;
  const line = revisedReportLine(block.line);
  return {...block,...structuredClone(entry.block??{}),line,criterion:line.criterion,objective:structuredClone(entry.controlObjective)};
}
export function revisedReportPoint(point) {
  const entry = reportQualityFor(point.legacy_line_id)?.points.find(p => p.id === point.id);
  if (!entry) return point;
  return {...point, ...structuredClone(entry.changes), generic_variant: structuredClone(entry.generic_variant),
    review_status: 'AI_REVIEWED_PRACTICAL_REVISION', human_validation: false, practical_revision: reportQualityVersion};
}
